use anyhow::Result;
use regex::Regex;
use serde::Deserialize;
use std::path::Path;

#[derive(Debug, Clone, Deserialize)]
pub struct FilterConfig {
    pub command: CommandMatch,
    #[serde(default)]
    pub strip_ansi: Option<bool>,
    #[serde(default)]
    pub replace: Vec<ReplaceRule>,
    #[serde(default)]
    pub match_output: Option<MatchOutputRule>,
    #[serde(default)]
    pub strip_lines: Vec<StripLinesRule>,
    #[serde(default)]
    pub truncate_lines: Option<TruncateLinesRule>,
    #[serde(default)]
    pub head_tail: Option<HeadTailRule>,
    #[serde(default)]
    pub max_lines: Option<usize>,
    #[serde(default)]
    pub on_empty: Option<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct CommandMatch {
    pub name: String,
    #[serde(default)]
    pub args_contain: Vec<String>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct ReplaceRule {
    pub pattern: String,
    pub replacement: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct MatchOutputRule {
    pub pattern: String,
    #[serde(default)]
    pub invert: bool,
}

#[derive(Debug, Clone, Deserialize)]
pub struct StripLinesRule {
    pub pattern: String,
}

#[derive(Debug, Clone, Deserialize)]
pub struct TruncateLinesRule {
    pub max_length: usize,
    #[serde(default = "default_suffix")]
    pub suffix: String,
}

fn default_suffix() -> String {
    "…".to_string()
}

#[derive(Debug, Clone, Deserialize)]
pub struct HeadTailRule {
    pub head: usize,
    pub tail: usize,
    #[serde(default = "default_separator")]
    pub separator: String,
}

fn default_separator() -> String {
    "\n... ({omitted} lines omitted) ...\n".to_string()
}

pub struct FilterPipeline {
    configs: Vec<FilterConfig>,
}

impl FilterPipeline {
    pub fn new() -> Self {
        Self { configs: Vec::new() }
    }

    pub fn load_from_dir(dir: &Path) -> Result<Self> {
        let mut configs = Vec::new();
        if dir.exists() {
            for entry in std::fs::read_dir(dir)? {
                let entry = entry?;
                let path = entry.path();
                if path.extension().is_some_and(|e| e == "toml") {
                    let content = std::fs::read_to_string(&path)?;
                    let config: FilterConfig = toml::from_str(&content)?;
                    configs.push(config);
                }
            }
        }
        Ok(Self { configs })
    }

    pub fn add_config(&mut self, config: FilterConfig) {
        self.configs.push(config);
    }

    pub fn find_filter(&self, command: &str, args: &[String]) -> Option<&FilterConfig> {
        self.configs.iter().find(|c| {
            if c.command.name != command {
                return false;
            }
            c.command.args_contain.iter().all(|required| {
                args.iter().any(|a| a.contains(required.as_str()))
            })
        })
    }

    pub fn apply(&self, command: &str, args: &[String], output: &str) -> FilterResult {
        let config = match self.find_filter(command, args) {
            Some(c) => c,
            None => return FilterResult::passthrough(output),
        };
        apply_filter(config, output)
    }
}

#[derive(Debug)]
pub struct FilterResult {
    pub output: String,
    pub input_len: usize,
    pub output_len: usize,
    pub filter_applied: bool,
}

impl FilterResult {
    fn passthrough(output: &str) -> Self {
        let len = output.len();
        Self {
            output: output.to_string(),
            input_len: len,
            output_len: len,
            filter_applied: false,
        }
    }
}

pub fn apply_filter(config: &FilterConfig, output: &str) -> FilterResult {
    let input_len = output.len();
    let mut text = output.to_string();

    // Stage 1: strip_ansi
    if config.strip_ansi.unwrap_or(true) {
        text = stage_strip_ansi(&text);
    }

    // Stage 2: replace
    for rule in &config.replace {
        text = stage_replace(&text, rule);
    }

    // Stage 3: match_output
    if let Some(rule) = &config.match_output {
        text = stage_match_output(&text, rule);
    }

    // Stage 4: strip_lines
    for rule in &config.strip_lines {
        text = stage_strip_lines(&text, rule);
    }

    // Stage 5: truncate_lines
    if let Some(rule) = &config.truncate_lines {
        text = stage_truncate_lines(&text, rule);
    }

    // Stage 6: head_tail
    if let Some(rule) = &config.head_tail {
        text = stage_head_tail(&text, rule);
    }

    // Stage 7: max_lines
    if let Some(max) = config.max_lines {
        text = stage_max_lines(&text, max);
    }

    // Stage 8: on_empty
    if let Some(fallback) = &config.on_empty {
        if text.trim().is_empty() {
            text = fallback.clone();
        }
    }

    let output_len = text.len();
    FilterResult {
        output: text,
        input_len,
        output_len,
        filter_applied: true,
    }
}

fn stage_strip_ansi(text: &str) -> String {
    match strip_ansi_escapes::strip_str(text) {
        s if s.is_empty() && !text.is_empty() => text.to_string(),
        s => s.to_string(),
    }
}

fn stage_replace(text: &str, rule: &ReplaceRule) -> String {
    match Regex::new(&rule.pattern) {
        Ok(re) => re.replace_all(text, rule.replacement.as_str()).to_string(),
        Err(_) => text.to_string(),
    }
}

fn stage_match_output(text: &str, rule: &MatchOutputRule) -> String {
    let re = match Regex::new(&rule.pattern) {
        Ok(r) => r,
        Err(_) => return text.to_string(),
    };
    let lines: Vec<&str> = text.lines().collect();
    let filtered: Vec<&str> = lines
        .into_iter()
        .filter(|line| {
            let matches = re.is_match(line);
            if rule.invert { !matches } else { matches }
        })
        .collect();
    filtered.join("\n")
}

fn stage_strip_lines(text: &str, rule: &StripLinesRule) -> String {
    let re = match Regex::new(&rule.pattern) {
        Ok(r) => r,
        Err(_) => return text.to_string(),
    };
    text.lines()
        .filter(|line| !re.is_match(line))
        .collect::<Vec<_>>()
        .join("\n")
}

fn stage_truncate_lines(text: &str, rule: &TruncateLinesRule) -> String {
    text.lines()
        .map(|line| {
            if line.len() > rule.max_length {
                let truncated: String = line.chars().take(rule.max_length).collect();
                format!("{}{}", truncated, rule.suffix)
            } else {
                line.to_string()
            }
        })
        .collect::<Vec<_>>()
        .join("\n")
}

fn stage_head_tail(text: &str, rule: &HeadTailRule) -> String {
    let lines: Vec<&str> = text.lines().collect();
    let total = lines.len();
    if total <= rule.head + rule.tail {
        return text.to_string();
    }
    let head_part: Vec<&str> = lines[..rule.head].to_vec();
    let tail_part: Vec<&str> = lines[total - rule.tail..].to_vec();
    let omitted = total - rule.head - rule.tail;
    let sep = rule.separator.replace("{omitted}", &omitted.to_string());
    format!("{}{}{}", head_part.join("\n"), sep, tail_part.join("\n"))
}

fn stage_max_lines(text: &str, max: usize) -> String {
    let lines: Vec<&str> = text.lines().collect();
    if lines.len() <= max {
        return text.to_string();
    }
    lines[..max].join("\n")
}

