        }));

        assert!(pipeline.find_filter("git", &["status".to_string()]).is_some());
        assert!(pipeline.find_filter("git", &["push".to_string()]).is_none());
        assert!(pipeline.find_filter("npm", &["test".to_string()]).is_some());
        assert!(pipeline.find_filter("unknown", &[]).is_none());
    }

    #[test]
    fn test_passthrough_when_no_filter() {
        let pipeline = FilterPipeline::new();
        let result = pipeline.apply("unknown", &[], "hello world");
        assert!(!result.filter_applied);
        assert_eq!(result.output, "hello world");
    }

    #[test]
    fn test_all_toml_filters_parse() {
        let filters_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../filters");
        assert!(filters_dir.exists(), "filters dir not found at {:?}", filters_dir);
        let pipeline = FilterPipeline::load_from_dir(&filters_dir).unwrap();
        let count = pipeline.configs.len();
        assert!(count >= 10, "expected at least 10 filters, found {}", count);

        let expected = [
            ("git", vec!["status"], true),
            ("git", vec!["diff"], true),
            ("git", vec!["log"], true),
            ("npm", vec!["test"], true),
            ("cargo", vec!["build"], true),
            ("cargo", vec!["test"], true),
            ("pytest", vec![], true),
            ("tsc", vec![], true),
            ("eslint", vec![], true),
            ("ls", vec![], true),
            ("docker", vec!["logs"], true),
            ("find", vec![], true),
            ("go", vec!["test"], true),
            ("pip", vec!["install"], true),
            ("grep", vec![], true),
        ];
        for (cmd, args, should_exist) in expected {
            let args: Vec<String> = args.into_iter().map(String::from).collect();
            let found = pipeline.find_filter(cmd, &args).is_some();
            assert_eq!(found, should_exist, "filter for '{} {:?}' expected={}", cmd, args, should_exist);
        }
    }
}

